-- Render/Postgres one-off apply script for equipment schema and normalized data.
--
-- Prerequisite: run the existing base schema/seed first, at least through
-- migrations 001-013 and db/seeds 001-005, so areas/studios/rooms/sources/
-- equipment_items already exist.
--
-- This file is intentionally kept outside migrations/seeds/manual-data.
-- Execute it manually for a new DB that needs the equipment evidence/model
-- changes and the normalized room equipment data from PR #167.

BEGIN;

-- -----------------------------------------------------------------------------
-- Source: src/api/db/migrations/014_equipment_evidence.sql
-- -----------------------------------------------------------------------------

CREATE TABLE IF NOT EXISTS equipment_evidence (
  id BIGSERIAL PRIMARY KEY,
  evidence_key VARCHAR(160) NOT NULL UNIQUE,
  target_kind VARCHAR(16) NOT NULL CHECK (target_kind IN ('STUDIO', 'ROOM')),
  studio_id BIGINT REFERENCES studios(id) ON DELETE CASCADE,
  room_id BIGINT REFERENCES rooms(id) ON DELETE CASCADE,
  equipment_id BIGINT REFERENCES equipment_items(id),
  source_kind VARCHAR(32) NOT NULL CHECK (
    source_kind IN (
      'NAVER_BOOKING',
      'NAVER_PLACE',
      'SPACE_CLOUD',
      'OFFICIAL_SITE',
      'SOCIAL',
      'BLOG',
      'UNKNOWN'
    )
  ),
  source_url VARCHAR(1024) NOT NULL,
  source_title VARCHAR(256),
  raw_name VARCHAR(160),
  raw_text TEXT NOT NULL,
  confidence VARCHAR(16) NOT NULL CHECK (
    confidence IN ('HIGH', 'MEDIUM', 'LOW', 'NEEDS_REVIEW')
  ),
  observed_at TIMESTAMPTZ NOT NULL DEFAULT now(),
  created_at TIMESTAMPTZ NOT NULL DEFAULT now(),
  CHECK (
    (target_kind = 'STUDIO' AND studio_id IS NOT NULL AND room_id IS NULL)
    OR
    (target_kind = 'ROOM' AND studio_id IS NULL AND room_id IS NOT NULL)
  )
);

CREATE INDEX IF NOT EXISTS idx_equipment_evidence_studio
  ON equipment_evidence (studio_id, equipment_id)
  WHERE studio_id IS NOT NULL;

CREATE INDEX IF NOT EXISTS idx_equipment_evidence_room
  ON equipment_evidence (room_id, equipment_id)
  WHERE room_id IS NOT NULL;

CREATE INDEX IF NOT EXISTS idx_equipment_evidence_review
  ON equipment_evidence (confidence, source_kind)
  WHERE confidence IN ('LOW', 'NEEDS_REVIEW') OR equipment_id IS NULL;


-- -----------------------------------------------------------------------------
-- Source: src/api/db/migrations/015_clear_autogenerated_equipment.sql
-- -----------------------------------------------------------------------------

DELETE FROM room_equipment
WHERE source = 'SCRAPED';

DELETE FROM studio_equipment
WHERE source = 'SCRAPED';

DELETE FROM equipment_evidence
WHERE source_kind = 'NAVER_BOOKING'
  AND observed_at = '2026-07-22T00:00:00+09:00'::timestamptz;


-- -----------------------------------------------------------------------------
-- Source: src/api/db/migrations/016_equipment_models.sql
-- -----------------------------------------------------------------------------

CREATE TABLE IF NOT EXISTS equipment_models (
  id BIGSERIAL PRIMARY KEY,
  equipment_id BIGINT NOT NULL REFERENCES equipment_items(id) ON DELETE CASCADE,
  slug VARCHAR(160) NOT NULL UNIQUE,
  brand VARCHAR(96),
  model VARCHAR(128) NOT NULL,
  variant VARCHAR(128),
  display_name VARCHAR(192) NOT NULL,
  normalized_name VARCHAR(192) NOT NULL,
  specs JSONB NOT NULL DEFAULT '{}'::jsonb,
  is_active BOOLEAN NOT NULL DEFAULT true,
  created_at TIMESTAMPTZ NOT NULL DEFAULT now(),
  updated_at TIMESTAMPTZ NOT NULL DEFAULT now()
);

ALTER TABLE room_equipment ADD COLUMN IF NOT EXISTS id BIGINT;
ALTER TABLE studio_equipment ADD COLUMN IF NOT EXISTS id BIGINT;

CREATE SEQUENCE IF NOT EXISTS room_equipment_id_seq;
CREATE SEQUENCE IF NOT EXISTS studio_equipment_id_seq;

ALTER SEQUENCE room_equipment_id_seq OWNED BY room_equipment.id;
ALTER SEQUENCE studio_equipment_id_seq OWNED BY studio_equipment.id;

ALTER TABLE room_equipment
  ALTER COLUMN id SET DEFAULT nextval('room_equipment_id_seq');

ALTER TABLE studio_equipment
  ALTER COLUMN id SET DEFAULT nextval('studio_equipment_id_seq');

UPDATE room_equipment
SET id = nextval('room_equipment_id_seq')
WHERE id IS NULL;

UPDATE studio_equipment
SET id = nextval('studio_equipment_id_seq')
WHERE id IS NULL;

SELECT setval(
  'room_equipment_id_seq',
  COALESCE((SELECT MAX(id) FROM room_equipment), 1),
  (SELECT COUNT(*) > 0 FROM room_equipment)
);

SELECT setval(
  'studio_equipment_id_seq',
  COALESCE((SELECT MAX(id) FROM studio_equipment), 1),
  (SELECT COUNT(*) > 0 FROM studio_equipment)
);

ALTER TABLE room_equipment
  ALTER COLUMN id SET NOT NULL;

ALTER TABLE studio_equipment
  ALTER COLUMN id SET NOT NULL;

DO $$
BEGIN
  IF EXISTS (
    SELECT 1
    FROM pg_constraint
    WHERE conname = 'room_equipment_pkey'
      AND conrelid = 'room_equipment'::regclass
      AND pg_get_constraintdef(oid) <> 'PRIMARY KEY (id)'
  ) THEN
    ALTER TABLE room_equipment DROP CONSTRAINT room_equipment_pkey;
  END IF;

  IF NOT EXISTS (
    SELECT 1
    FROM pg_constraint
    WHERE conname = 'room_equipment_pkey'
      AND conrelid = 'room_equipment'::regclass
  ) THEN
    ALTER TABLE room_equipment ADD CONSTRAINT room_equipment_pkey PRIMARY KEY (id);
  END IF;

  IF EXISTS (
    SELECT 1
    FROM pg_constraint
    WHERE conname = 'studio_equipment_pkey'
      AND conrelid = 'studio_equipment'::regclass
      AND pg_get_constraintdef(oid) <> 'PRIMARY KEY (id)'
  ) THEN
    ALTER TABLE studio_equipment DROP CONSTRAINT studio_equipment_pkey;
  END IF;

  IF NOT EXISTS (
    SELECT 1
    FROM pg_constraint
    WHERE conname = 'studio_equipment_pkey'
      AND conrelid = 'studio_equipment'::regclass
  ) THEN
    ALTER TABLE studio_equipment ADD CONSTRAINT studio_equipment_pkey PRIMARY KEY (id);
  END IF;
END $$;

ALTER TABLE room_equipment
  ADD COLUMN IF NOT EXISTS equipment_model_id BIGINT REFERENCES equipment_models(id),
  ADD COLUMN IF NOT EXISTS position_label VARCHAR(64),
  ADD COLUMN IF NOT EXISTS is_optional BOOLEAN NOT NULL DEFAULT false,
  ADD COLUMN IF NOT EXISTS details JSONB NOT NULL DEFAULT '{}'::jsonb;

ALTER TABLE studio_equipment
  ADD COLUMN IF NOT EXISTS equipment_model_id BIGINT REFERENCES equipment_models(id),
  ADD COLUMN IF NOT EXISTS position_label VARCHAR(64),
  ADD COLUMN IF NOT EXISTS is_optional BOOLEAN NOT NULL DEFAULT false,
  ADD COLUMN IF NOT EXISTS details JSONB NOT NULL DEFAULT '{}'::jsonb;

ALTER TABLE equipment_evidence
  ADD COLUMN IF NOT EXISTS equipment_model_id BIGINT REFERENCES equipment_models(id),
  ADD COLUMN IF NOT EXISTS room_equipment_id BIGINT REFERENCES room_equipment(id) ON DELETE SET NULL,
  ADD COLUMN IF NOT EXISTS studio_equipment_id BIGINT REFERENCES studio_equipment(id) ON DELETE SET NULL,
  ADD COLUMN IF NOT EXISTS parsed_name VARCHAR(192),
  ADD COLUMN IF NOT EXISTS position_label VARCHAR(64),
  ADD COLUMN IF NOT EXISTS is_optional BOOLEAN NOT NULL DEFAULT false;

CREATE INDEX IF NOT EXISTS idx_equipment_models_equipment
  ON equipment_models (equipment_id, is_active, display_name);

CREATE INDEX IF NOT EXISTS idx_equipment_models_normalized
  ON equipment_models (lower(normalized_name));

CREATE UNIQUE INDEX IF NOT EXISTS idx_room_equipment_unique_assignment
  ON room_equipment (
    room_id,
    equipment_id,
    COALESCE(equipment_model_id, 0),
    COALESCE(position_label, '')
  );

CREATE UNIQUE INDEX IF NOT EXISTS idx_studio_equipment_unique_assignment
  ON studio_equipment (
    studio_id,
    equipment_id,
    COALESCE(equipment_model_id, 0),
    COALESCE(position_label, '')
  );

CREATE INDEX IF NOT EXISTS idx_room_equipment_model
  ON room_equipment (equipment_model_id)
  WHERE equipment_model_id IS NOT NULL;

CREATE INDEX IF NOT EXISTS idx_studio_equipment_model
  ON studio_equipment (equipment_model_id)
  WHERE equipment_model_id IS NOT NULL;

CREATE INDEX IF NOT EXISTS idx_equipment_evidence_model
  ON equipment_evidence (equipment_model_id)
  WHERE equipment_model_id IS NOT NULL;


-- -----------------------------------------------------------------------------
-- Source: src/api/db/manual-data/001_soundcity_keyboard_equipment.sql
-- -----------------------------------------------------------------------------

WITH model_seed(equipment_slug, slug, brand, model, variant, display_name, normalized_name, specs) AS (
  VALUES
    ('keyboard', 'yamaha-s90', 'Yamaha', 'S90', NULL, 'Yamaha S90', 'yamaha s90', '{}'::jsonb),
    ('keyboard', 'yamaha-s90es', 'Yamaha', 'S90ES', NULL, 'Yamaha S90ES', 'yamaha s90es', '{}'::jsonb),
    ('keyboard', 'yamaha-motif-7', 'Yamaha', 'Motif 7', NULL, 'Yamaha Motif 7', 'yamaha motif 7', '{}'::jsonb),
    ('keyboard', 'yamaha-motif-es8', 'Yamaha', 'Motif ES8', NULL, 'Yamaha Motif ES8', 'yamaha motif es8', '{}'::jsonb),
    ('keyboard', 'yamaha-motif-xf8', 'Yamaha', 'Motif XF8', NULL, 'Yamaha Motif XF8', 'yamaha motif xf8', '{}'::jsonb),
    ('keyboard', 'yamaha-modx7-plus', 'Yamaha', 'MODX7+', NULL, 'Yamaha MODX7+', 'yamaha modx7 plus', '{}'::jsonb),
    ('keyboard', 'korg-kross-61', 'Korg', 'Kross 61', NULL, 'Korg Kross 61', 'korg kross 61', '{}'::jsonb)
)
  equipment_id,
  slug,
  brand,
  model,
  variant,
  display_name,
  normalized_name,
  specs
)
SELECT
  ei.id,
  model_seed.slug,
  model_seed.brand,
  model_seed.model,
  model_seed.variant,
  model_seed.display_name,
  model_seed.normalized_name,
  model_seed.specs
FROM model_seed
JOIN equipment_items ei ON ei.slug = model_seed.equipment_slug
ON CONFLICT (slug) DO UPDATE SET
  equipment_id = EXCLUDED.equipment_id,
  brand = EXCLUDED.brand,
  model = EXCLUDED.model,
  variant = EXCLUDED.variant,
  display_name = EXCLUDED.display_name,
  normalized_name = EXCLUDED.normalized_name,
  specs = EXCLUDED.specs,
  is_active = true,
  updated_at = now();

