  placement_seed.position_label,
  placement_seed.is_optional,
  placement_seed.details
FROM placement_seed
JOIN studios s ON s.slug = placement_seed.studio_slug
JOIN rooms r ON r.studio_id = s.id AND r.name = placement_seed.room_name
